// Reveal.js 6 — HTML presentation framework
import Reveal from 'reveal.js';
import 'reveal.js/reset.css';
import 'reveal.js/reveal.css';
import 'reveal.js/theme/white.css';

const SAMPLE_SLIDES = `
<section>
  <h1>Office 改造方案 POC</h1>
  <p style="margin-top: 1.5em; color: #6b6b6b;">Univer + Tiptap + Reveal.js — 纯前端，零服务端</p>
  <p style="margin-top: 3em; font-size: 0.5em; color: #999;">↓ 方向键翻页</p>
</section>
<section>
  <h2>为什么现在改？</h2>
  <ul>
    <li class="fragment">office-editor.js 是 contenteditable 假编辑器（Excel/PPT 无公式/无母版）</li>
    <li class="fragment">/api/office/save 写 JSON 后缀 .docx，Office/WPS 打不开</li>
    <li class="fragment">office-gen.js 三个 tool 是死代码（无 require）</li>
    <li class="fragment">LLM 只能产 docx，xlsx/pptx 走不到</li>
  </ul>
</section>
<section>
  <h2>三档方案对比</h2>
  <table style="font-size: 0.6em; margin: 1em auto;">
    <thead>
      <tr><th>方案</th><th>见效果</th><th>接入</th><th>服务端</th></tr>
    </thead>
    <tbody>
      <tr><td>Univer+Tiptap+Reveal（推荐）</td><td>30 分钟</td><td>★★☆</td><td>0</td></tr>
      <tr><td>ONLYOFFICE+WOPI 自托管</td><td>数小时</td><td>★★★</td><td>4GB+</td></tr>
      <tr><td>Google/Microsoft iframe</td><td>5 分钟</td><td>★☆☆</td><td>0</td></tr>
    </tbody>
  </table>
</section>
<section>
  <h2>ACMS 改造落地路径</h2>
  <ol>
    <li class="fragment"><strong>P0</strong>：修 office-gen.js 死代码（10 行 require）</li>
    <li class="fragment"><strong>P0</strong>：/api/office/save 写真 docx/xlsx/pptx</li>
    <li class="fragment"><strong>P1</strong>：office-editor.js 改造成 Tiptap+Univer+Reveal</li>
    <li class="fragment"><strong>P2</strong>：可选自托管 OO Document Server 做协作</li>
  </ol>
</section>
<section>
  <h1>Q&amp;A</h1>
  <p style="margin-top: 2em;">Esc 看缩略图，? 看所有快捷键</p>
</section>
`;

export function mountSlides() {
  const slidesRoot = document.querySelector('.reveal .slides');
  if (slidesRoot) slidesRoot.innerHTML = SAMPLE_SLIDES.trim();
  const deck = new Reveal({ hash: true, controls: true, progress: true, slideNumber: 'c/t', transition: 'slide' });
  deck.initialize();
  console.info('[Reveal] deck ready');
  return deck;
}